import type { HTMLArkProps } from '@ark-ui/react/factory';
import { ark } from '@ark-ui/react/factory';
import { clsx } from 'clsx';
import { forwardRef } from 'react';
import { a11yLabels } from '@/lib/moduix/a11yLabels';
import styles from './Table.module.css';

type TableSize = 'sm' | 'md' | 'lg';
type TableRootProps = HTMLArkProps<'table'> & {
  interactive?: boolean;
  showColumnBorder?: boolean;
  size?: TableSize;
  stickyHeader?: boolean;
  striped?: boolean;
};
type TableCaptionProps = HTMLArkProps<'caption'> & {
  side?: 'top' | 'bottom';
};
type TableColumnHeaderProps = HTMLArkProps<'th'> & {
  numeric?: boolean;
};
type TableCellProps = HTMLArkProps<'td'> & {
  numeric?: boolean;
};
type TableEmptyProps = HTMLArkProps<'td'> & {
  colSpan: number;
};

const Table = forwardRef<HTMLTableElement, TableRootProps>(function Table(
  {
    className,
    interactive = false,
    showColumnBorder = false,
    size = 'md',
    stickyHeader = false,
    striped = false,
    ...props
  },
  ref,
) {
  return (
    <ark.table
      ref={ref}
      className={clsx(styles.root, className)}
      {...props}
      data-scope="table"
      data-part="root"
      data-interactive={interactive || undefined}
      data-show-column-border={showColumnBorder || undefined}
      data-size={size}
      data-sticky-header={stickyHeader || undefined}
      data-striped={striped || undefined}
      data-slot="table-root"
    />
  );
});

const TableScrollArea = forwardRef<HTMLDivElement, HTMLArkProps<'div'>>(function TableScrollArea(
  { className, ...props },
  ref,
) {
  return (
    <ark.div
      ref={ref}
      className={clsx(styles.scrollArea, className)}
      {...props}
      data-scope="table"
      data-part="scroll-area"
      data-slot="table-scroll-area"
    />
  );
});

const TableCaption = forwardRef<HTMLTableCaptionElement, TableCaptionProps>(function TableCaption(
  { className, side = 'bottom', ...props },
  ref,
) {
  return (
    <ark.caption
      ref={ref}
      className={clsx(styles.caption, className)}
      {...props}
      data-scope="table"
      data-part="caption"
      data-side={side}
      data-slot="table-caption"
    />
  );
});

const TableColumnGroup = forwardRef<HTMLTableColElement, HTMLArkProps<'colgroup'>>(
  function TableColumnGroup(props, ref) {
    return (
      <ark.colgroup
        ref={ref}
        {...props}
        data-scope="table"
        data-part="column-group"
        data-slot="table-column-group"
      />
    );
  },
);

const TableColumn = forwardRef<HTMLTableColElement, HTMLArkProps<'col'>>(
  function TableColumn(props, ref) {
    return (
      <ark.col
        ref={ref}
        {...props}
        data-scope="table"
        data-part="column"
        data-slot="table-column"
      />
    );
  },
);

const TableHeader = forwardRef<HTMLTableSectionElement, HTMLArkProps<'thead'>>(function TableHeader(
  { className, ...props },
  ref,
) {
  return (
    <ark.thead
      ref={ref}
      className={clsx(styles.header, className)}
      {...props}
      data-scope="table"
      data-part="header"
      data-slot="table-header"
    />
  );
});

const TableBody = forwardRef<HTMLTableSectionElement, HTMLArkProps<'tbody'>>(function TableBody(
  { className, ...props },
  ref,
) {
  return (
    <ark.tbody
      ref={ref}
      className={clsx(styles.body, className)}
      {...props}
      data-scope="table"
      data-part="body"
      data-slot="table-body"
    />
  );
});

const TableFooter = forwardRef<HTMLTableSectionElement, HTMLArkProps<'tfoot'>>(function TableFooter(
  { className, ...props },
  ref,
) {
  return (
    <ark.tfoot
      ref={ref}
      className={clsx(styles.footer, className)}
      {...props}
      data-scope="table"
      data-part="footer"
      data-slot="table-footer"
    />
  );
});

const TableRow = forwardRef<HTMLTableRowElement, HTMLArkProps<'tr'>>(function TableRow(
  { className, ...props },
  ref,
) {
  return (
    <ark.tr
      ref={ref}
      className={clsx(styles.row, className)}
      {...props}
      data-scope="table"
      data-part="row"
      data-slot="table-row"
    />
  );
});

const TableColumnHeader = forwardRef<HTMLTableCellElement, TableColumnHeaderProps>(
  function TableColumnHeader({ className, numeric = false, ...props }, ref) {
    return (
      <ark.th
        ref={ref}
        className={clsx(styles.columnHeader, numeric && styles.numeric, className)}
        {...props}
        data-scope="table"
        data-part="column-header"
        data-numeric={numeric || undefined}
        data-slot="table-column-header"
      />
    );
  },
);

const TableCell = forwardRef<HTMLTableCellElement, TableCellProps>(function TableCell(
  { className, numeric = false, ...props },
  ref,
) {
  return (
    <ark.td
      ref={ref}
      className={clsx(styles.cell, numeric && styles.numeric, className)}
      {...props}
      data-scope="table"
      data-part="cell"
      data-numeric={numeric || undefined}
      data-slot="table-cell"
    />
  );
});

const TableEmpty = forwardRef<HTMLTableCellElement, TableEmptyProps>(function TableEmpty(
  { children = a11yLabels.noResults, className, ...props },
  ref,
) {
  return (
    <TableRow data-empty>
      <ark.td
        ref={ref}
        className={clsx(styles.cell, styles.empty, className)}
        {...props}
        data-scope="table"
        data-part="empty"
        data-slot="table-empty"
      >
        {children}
      </ark.td>
    </TableRow>
  );
});

export {
  Table,
  TableBody,
  TableCaption,
  TableCell,
  TableColumn,
  TableColumnGroup,
  TableColumnHeader,
  TableEmpty,
  TableFooter,
  TableHeader,
  TableRow,
  TableScrollArea,
};
export type { TableRootProps, TableSize };

@layer moduix.components {
  .scrollArea {
    box-sizing: border-box;
    position: relative;
    width: 100%;
    min-width: 0;
    overflow-x: auto;
    border: var(--moduix-border-width-sm) solid
      var(--moduix-table-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-radius-lg);
    background-color: var(--moduix-table-bg, var(--moduix-color-card));
  }

  .root {
    --_table-cell-padding-x: var(--moduix-table-cell-padding-x, var(--moduix-spacing-4));
    --_table-cell-padding-y: var(--moduix-table-cell-padding-y, var(--moduix-spacing-3));

    width: 100%;
    border-collapse: collapse;
    color: var(--moduix-color-foreground);
    font-size: var(--moduix-text-sm);
    line-height: var(--moduix-line-height-text-sm);
    text-align: start;
    isolation: isolate;

    &[data-size='sm'] {
      --_table-cell-padding-x: var(--moduix-table-cell-padding-x, var(--moduix-spacing-3));
      --_table-cell-padding-y: var(--moduix-table-cell-padding-y, var(--moduix-spacing-2));
      font-size: var(--moduix-text-xs);
      line-height: var(--moduix-line-height-text-xs);
    }

    &[data-size='lg'] {
      --_table-cell-padding-x: var(--moduix-table-cell-padding-x, var(--moduix-spacing-5));
      --_table-cell-padding-y: var(--moduix-table-cell-padding-y, var(--moduix-spacing-4));
      font-size: var(--moduix-text-md);
      line-height: var(--moduix-line-height-text-md);
    }
  }

  .caption {
    padding-inline: var(--_table-cell-padding-x);
    color: var(--moduix-color-muted-foreground);
    font-size: var(--moduix-text-sm);
    line-height: var(--moduix-line-height-text-sm);
    text-align: start;
    text-wrap: pretty;

    &[data-side='top'] {
      caption-side: top;
      padding-block: var(--moduix-spacing-2) var(--moduix-spacing-3);
    }

    &[data-side='bottom'] {
      caption-side: bottom;
      padding-block: var(--moduix-spacing-3) var(--moduix-spacing-2);
    }
  }

  .root[data-sticky-header] .header {
    position: sticky;
    inset-block-start: 0;
    z-index: 3;
    background-color: var(--moduix-table-bg, var(--moduix-color-card));
  }

  .footer {
    border-top: var(--moduix-border-width-sm) solid
      var(--moduix-table-border-color, var(--moduix-color-border));
    background-color: var(--moduix-color-muted);
    font-weight: var(--moduix-weight-medium);
  }

  /* Sticky cells repaint the row state over their own background through --_table-row-bg. */
  .row {
    --_table-row-bg: initial;

    background-color: var(--_table-row-bg, transparent);
  }

  .header .row,
  .body .row:not(:last-child) {
    border-bottom: var(--moduix-border-width-sm) solid
      var(--moduix-table-border-color, var(--moduix-color-border));
  }

  .root[data-striped] .body .row:nth-child(even):not([data-empty]) {
    --_table-row-bg: var(
      --moduix-table-row-bg-striped,
      color-mix(in oklab, var(--moduix-color-muted) 35%, transparent)
    );
  }

  @media (hover: hover) {
    .root[data-interactive] .body .row:not([data-empty]):hover {
      --_table-row-bg: var(--moduix-table-row-bg-hover, var(--moduix-color-muted));
    }
  }

  .root[data-interactive] .body .row:not([data-empty]):focus-within {
    --_table-row-bg: var(--moduix-table-row-bg-hover, var(--moduix-color-muted));
  }

  .columnHeader,
  .cell {
    position: relative;
    z-index: 0;
    padding-block: var(--_table-cell-padding-y);
    padding-inline: var(--_table-cell-padding-x);

    &[data-sticky] {
      position: sticky;
      z-index: 2;
      background-color: var(--moduix-table-bg, var(--moduix-color-card));
      background-image: linear-gradient(var(--_table-row-bg), var(--_table-row-bg));
    }

    &[data-sticky='start'] {
      inset-inline-start: 0;
    }

    &[data-sticky='end'] {
      inset-inline-end: 0;
    }
  }

  .root[data-show-column-border] :is(.columnHeader, .cell):not(:last-child) {
    border-inline-end: var(--moduix-border-width-sm) solid
      var(--moduix-table-border-color, var(--moduix-color-border));
  }

  .columnHeader {
    color: var(--moduix-color-muted-foreground);
    font-weight: var(--moduix-weight-medium);
    text-align: inherit;
    white-space: nowrap;
  }

  .numeric {
    text-align: end;
    white-space: nowrap;
    font-variant-numeric: tabular-nums;
  }

  .empty {
    padding-block: calc(var(--_table-cell-padding-y) * 2);
    color: var(--moduix-color-muted-foreground);
    text-align: center;
  }
}
